const assert = require('assert');

// Test cases
try {
  assert.strictEqual(extractDomain('https://www.google.com/search'), 'www.google.com');
  assert.strictEqual(extractDomain('http://localhost:3000/api'), 'localhost');
  assert.strictEqual(extractDomain('google.com'), 'google.com');
  assert.strictEqual(extractDomain('user:pass@example.io/path'), 'example.io');
  assert.strictEqual(extractDomain('ftp://files.server.net'), 'files.server.net');

  // Test for invalid inputs
  assert.throws(() => extractDomain(''), /Invalid input/);
  assert.throws(() => extractDomain(null), /Invalid input/);
  assert.throws(() => extractDomain('!!!'), /Invalid URL/);

  console.log('All tests passed successfully.');
} catch (error) {
  console.error('Test failed:', error.message);
}
